"""Embedded, dependency-free browser interface for live capture and knowledge retrieval."""

PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NoteTaker / Knowledge Capture</title>
<style>
:root{--ink:#18231f;--muted:#6e7c76;--paper:#f4f1e9;--card:#fffdf8;--line:#d9d7ce;--accent:#d85f3d;--green:#305d4d;--warn:#9b661e;--danger:#9e3b2d;--shadow:0 18px 55px #1c342415}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.6 Inter,ui-sans-serif,system-ui,sans-serif}button,input{font:inherit}button{cursor:pointer;border:0}.shell{max-width:1440px;margin:auto;padding:24px 28px 70px}.top{display:flex;align-items:flex-start;gap:24px;border-bottom:1px solid var(--line);padding-bottom:20px}.mark{font:700 12px ui-monospace,monospace;letter-spacing:.18em;color:var(--accent)}h1{margin:5px 0 0;font:700 clamp(32px,5vw,66px)/.95 Georgia,serif;letter-spacing:-.05em}.subtitle{max-width:480px;margin:7px 0 0;color:var(--muted)}.top .grow,.grow{flex:1}.pill{border:1px solid var(--line);border-radius:999px;padding:7px 12px;color:var(--muted);font:12px ui-monospace,monospace;white-space:nowrap}.controls{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:18px 0}.model-picker{display:grid;gap:3px;min-width:min(100%,360px);margin-right:4px}.model-picker select{border:1px solid var(--line);border-radius:4px;background:var(--card);color:var(--ink);padding:8px 30px 8px 10px;min-width:260px}.model-picker select:disabled{opacity:.65;cursor:not-allowed}.model-picker .hint{font-size:12px;line-height:1.35}.btn{background:var(--ink);color:white;border-radius:4px;padding:10px 16px;font-weight:700}.btn:hover{background:var(--green)}.btn.secondary{background:transparent;color:var(--ink);border:1px solid var(--ink)}.btn.live{background:var(--accent)}.grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(340px,.9fr);gap:20px}.panel{background:var(--card);border:1px solid var(--line);box-shadow:var(--shadow);border-radius:8px;padding:20px}.panel h2{font:700 23px Georgia,serif;margin:0 0 5px}.kicker{font:11px ui-monospace,monospace;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}.live-log{min-height:420px;max-height:650px;overflow:auto;margin-top:18px}.segment{border-top:1px solid var(--line);padding:15px 0;display:grid;grid-template-columns:100px 1fr;gap:15px}.segment:first-child{border-top:0}.stamp{color:var(--muted);font:12px ui-monospace,monospace}.speaker{font-size:11px;color:var(--green);text-transform:uppercase;letter-spacing:.1em}.low{color:var(--warn);background:#f8e9c9;padding:1px 4px;border-radius:3px}.hint{color:var(--muted);font-size:14px}.summary{display:grid;gap:12px;margin-top:18px}.note-card{border-top:1px solid var(--line);padding:14px 0}.note-card strong{font-family:Georgia,serif;font-size:18px}.note-card ul{padding-left:20px}.search{display:flex;gap:8px;margin:14px 0}.search input{flex:1;border:1px solid var(--line);border-radius:4px;background:white;padding:9px 11px}.results{display:grid;gap:8px}.result{padding:10px;border:1px solid var(--line);border-radius:4px}.result a{color:var(--green);font-weight:700;cursor:pointer}.exports{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}.exports a{color:var(--green);font:12px ui-monospace,monospace}.meter{height:5px;background:#e4e1d7;border-radius:4px;overflow:hidden;margin:14px 0}.meter i{display:block;height:100%;width:0;background:var(--accent);transition:width .1s}.empty{padding:45px 10px;text-align:center;color:var(--muted)}.empty-row{display:block;color:var(--warn);background:#fff8e9;border:1px solid #ead5a7;border-radius:5px;padding:12px 14px;margin-top:12px}.banner{display:none;border:1px solid #e2bd70;background:#fff2ca;color:#704b12;border-radius:5px;padding:12px 14px;margin:0 0 16px;font-weight:700}.banner.show{display:block}.banner.danger{border-color:#d59c91;background:#fff0ed;color:var(--danger)}details{border-top:1px solid var(--line);padding:12px 0}summary{cursor:pointer;font-weight:700}@media(max-width:900px){.grid{grid-template-columns:1fr}.top{display:block}.top .pill{display:inline-block;margin-top:18px}.shell{padding:18px 15px}.segment{grid-template-columns:76px 1fr}}
</style></head><body><div class="shell">
<header class="top"><div><div class="mark">NT / 02 — HIGH-FIDELITY KNOWLEDGE CAPTURE</div><h1>Keep the signal.</h1><p class="subtitle">Live transcription that preserves reasoning, evidence, decisions, and the details worth finding again.</p></div><div class="grow"></div><span class="pill" id="model">local pipeline</span></header>
<section class="controls"><button class="btn" id="record">Start capture</button><button class="btn secondary" id="clear">Clear live view</button><label class="model-picker" for="model-select"><span class="kicker">CPU transcription model</span><select id="model-select" aria-describedby="model-help"></select><span class="hint" id="model-help">Large-v3 Turbo · faster live CPU capture.</span></label><span class="pill" id="status">idle</span><span class="pill" id="words">0 words</span><span class="pill" id="queue">queued: 0</span><span class="pill" id="rtf">RTF: —</span><div class="grow"></div><span class="hint" id="message">Audio stays local unless an optional provider is configured.</span></section>
<div id="performance-banner" class="banner" role="status"></div><div id="watchdog-banner" class="banner danger" role="alert"></div>
<div class="grid"><section class="panel"><div class="kicker">Live evidence ledger</div><h2>Transcript, not just a summary</h2><p class="hint">Every segment retains timestamps, words, confidence, language, and speaker metadata. Low-confidence regions are marked for review.</p><div class="meter"><i id="meter"></i></div><div id="live" class="live-log"><div class="empty">Press <b>Start capture</b>, allow microphone access, and speak.</div></div></section>
<section class="panel"><div class="kicker">Knowledge base</div><h2>Find what you already captured</h2><div class="search"><input id="query" placeholder="Search concepts, names, deadlines, URLs…"><button class="btn" id="search">Search</button></div><div id="results" class="results"><div class="empty">Saved notes, concepts, actions, questions, and timestamps appear here.</div></div><div id="selected" class="summary"></div></section></div>
</div><script>
const $=selector=>document.querySelector(selector);
const fallbackModelOptions=[
 {id:'large-v3',label:'Large-v3 · Offline / slower than real time',checkpoint:'large-v3',repository:'https://huggingface.co/Systran/faster-whisper-large-v3',description:'Best general accuracy; reserve for offline-quality transcription.',speed:'offline',quality:'best'},
 {id:'large-v3-max',label:'Large-v3 · Maximum CPU decode',checkpoint:'large-v3',repository:'https://huggingface.co/Systran/faster-whisper-large-v3',description:'Same offline model with the widest final beam.',speed:'extreme',quality:'maximum'},
 {id:'qwen3-asr-1.7b',label:'Qwen3-ASR · 1.7B · Multilingual',checkpoint:'Qwen/Qwen3-ASR-1.7B-hf',repository:'https://huggingface.co/Qwen/Qwen3-ASR-1.7B-hf',description:'Dedicated multilingual ASR; very slow CPU path.',speed:'very slow',quality:'excellent'},
 {id:'voxtral-mini-3b',label:'Voxtral Mini · 3B · Transcription',checkpoint:'mistralai/Voxtral-Mini-3B-2507',repository:'https://huggingface.co/mistralai/Voxtral-Mini-3B-2507',description:'Long-form transcription model; extreme CPU path.',speed:'extreme',quality:'very high'},
 {id:'qwen2-audio-7b',label:'Qwen2-Audio · 7B · Deep audio',checkpoint:'Qwen/Qwen2-Audio-7B-Instruct',repository:'https://huggingface.co/Qwen/Qwen2-Audio-7B-Instruct',description:'Largest audio-language option; needs substantial RAM.',speed:'extreme',quality:'very high'},
 {id:'distil-large-v3',label:'Distil-large-v3 · High quality',checkpoint:'distil-large-v3',repository:'https://huggingface.co/Systran/faster-distil-whisper-large-v3',description:'High-quality distilled checkpoint with lower CPU cost.',speed:'slow',quality:'very high'},
 {id:'large-v3-turbo',label:'Large-v3 Turbo · Faster',checkpoint:'large-v3-turbo',repository:'https://huggingface.co/deepdml/faster-whisper-large-v3-turbo-ct2',description:'Recommended practical default for live CPU capture.',speed:'fast',quality:'high'},
 {id:'medium',label:'Medium · Multilingual',checkpoint:'medium',repository:'https://huggingface.co/Systran/faster-whisper-medium',description:'Balanced multilingual checkpoint.',speed:'slow',quality:'high'},
 {id:'medium.en',label:'Medium English',checkpoint:'medium.en',repository:'https://huggingface.co/Systran/faster-whisper-medium.en',description:'Strong English-only CPU checkpoint.',speed:'slow',quality:'high'},
 {id:'small',label:'Small · Multilingual',checkpoint:'small',repository:'https://huggingface.co/Systran/faster-whisper-small',description:'Lighter multilingual checkpoint.',speed:'medium',quality:'good'},
 {id:'small.en',label:'Small English',checkpoint:'small.en',repository:'https://huggingface.co/Systran/faster-whisper-small.en',description:'Faster English-only checkpoint.',speed:'medium',quality:'good'},
 {id:'base',label:'Base · Multilingual',checkpoint:'base',repository:'https://huggingface.co/Systran/faster-whisper-base',description:'Lightweight multilingual fallback.',speed:'fast',quality:'moderate'},
 {id:'base.en',label:'Base English',checkpoint:'base.en',repository:'https://huggingface.co/Systran/faster-whisper-base.en',description:'Lightweight English-only fallback.',speed:'fast',quality:'moderate'},
 {id:'tiny',label:'Tiny · Multilingual',checkpoint:'tiny',repository:'https://huggingface.co/Systran/faster-whisper-tiny',description:'Smallest multilingual option.',speed:'fastest',quality:'basic'},
 {id:'tiny.en',label:'Tiny English',checkpoint:'tiny.en',repository:'https://huggingface.co/Systran/faster-whisper-tiny.en',description:'Smallest English-only draft/fallback model.',speed:'fastest',quality:'basic'}
];
let ws,ctx,node,stream,running=false,segments=[],lines=[],selectedModel='large-v3-turbo',modelOptions=fallbackModelOptions;
let draftNode=null,sourceRate=16000,flushPending=false,flushResolver=null,flushRejecter=null,flushTimer=null,measuredRtf=null,speechDetectedAt=0,lastOutputAt=0;
try{selectedModel=localStorage.getItem('notetaker-model')||selectedModel}catch(error){}
const stamp=seconds=>{const value=Math.max(0,Math.floor(Number(seconds)||0));return [Math.floor(value/3600),Math.floor(value/60)%60,value%60].map(v=>String(v).padStart(2,'0')).join(':')};
function setStatus(value,message=''){ $('#status').textContent=value;if(message)$('#message').textContent=message }
function showError(error){const message=error instanceof Error?error.message:String(error);setStatus('error',message);$('#status').title=message;showBanner('watchdog-banner',message,true)}
function setModelState(status){if(!status)return;const state=status.state||'unknown',profile=status.profile||selectedModelOption(),label=profile.label||status.profile_id||'selected model',loaded=(status.loaded||[]).join(', ');$('#model').textContent=state==='ready'?`${label} ready${loaded?' · '+loaded:''}`:state==='loading'?`${label} loading…`:state==='error'?`${label} error${status.error?' · '+status.error:''}`:state==='not-loaded'?`${label} waiting`:`${label} ${state}`;if(status.benchmark)showBenchmark(status.benchmark)}
function waitForSocket(socket,timeout=10000){return new Promise((resolve,reject)=>{let settled=false;const finish=(fn,value)=>{if(settled)return;settled=true;clearTimeout(timer);fn(value)};const timer=setTimeout(()=>{socket.close();finish(reject,new Error('WebSocket connection timed out'))},timeout);socket.addEventListener('open',()=>finish(resolve),{once:true});socket.addEventListener('error',()=>finish(reject,new Error('Could not connect to the NoteTaker WebSocket')),{once:true});socket.addEventListener('close',()=>finish(reject,new Error('NoteTaker WebSocket closed before capture started')),{once:true})})}
function showBanner(id,text,danger=false){const banner=$('#'+id);if(!banner)return;if(text){banner.textContent=text;banner.classList.add('show');if(danger)banner.classList.add('danger')}else{banner.textContent='';banner.classList.remove('show');if(!danger)banner.classList.remove('danger')}}
function showBenchmark(benchmark){if(typeof benchmark.rtf==='number'){$('#rtf').textContent=`RTF: ${benchmark.rtf.toFixed(2)}×`;measuredRtf=benchmark.rtf}if(benchmark.warning&&benchmark.message)showBanner('performance-banner',benchmark.message);else if(benchmark.state==='error')$('#message').textContent=benchmark.message||'Startup benchmark unavailable.'}
function renderSegment(segment,partial=false){const el=document.createElement('article');el.className='segment';const confidence=segment.confidence??0;el.innerHTML=`<div><div class="stamp">${stamp(segment.start)}–${stamp(segment.end)}</div><div class="speaker">${escapeHtml(segment.speaker||'Unknown speaker')}</div></div><div>${partial?'<em>draft · </em>':''}${confidence<.65?'<span class="low">review</span> ':''}${escapeHtml(segment.text)}<div class="hint">${escapeHtml(segment.language||'auto')} · ${Math.round(confidence*100)}% confidence</div></div>`;return el}
function renderEmpty(message,details=''){const el=document.createElement('article');el.className='segment empty-row';el.innerHTML=`<strong>${escapeHtml(message)}</strong>${details?`<div class="hint">${escapeHtml(details)}</div>`:''}`;return el}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function addSegment(segment){if(!segment.text)return;segments.push(segment);const live=$('#live');if(live.querySelector('.empty'))live.innerHTML='';if(draftNode){draftNode.remove();draftNode=null}live.append(renderSegment(segment));live.scrollTop=live.scrollHeight;lines.push(segment.text);$('#words').textContent=lines.join(' ').trim().split(/\s+/).filter(Boolean).length+' words';lastOutputAt=Date.now();speechDetectedAt=0;showBanner('watchdog-banner','')}
function showPartial(segment){if(!segment.text)return;const live=$('#live');if(live.querySelector('.empty'))live.innerHTML='';if(draftNode)draftNode.remove();draftNode=renderSegment({...segment,speaker:'Draft',confidence:.5},true);live.append(draftNode);live.scrollTop=live.scrollHeight;lastOutputAt=Date.now();speechDetectedAt=0;showBanner('watchdog-banner','')}
function updateQueue(depth){const value=Number.isFinite(Number(depth))?Number(depth):0;$('#queue').textContent=`queued: ${value}`}
function resolveFlush(message){if(!flushResolver)return;const resolve=flushResolver;clearTimeout(flushTimer);flushResolver=null;flushRejecter=null;flushTimer=null;resolve(message)}
function waitForFlush(timeout=45000){return new Promise((resolve,reject)=>{clearTimeout(flushTimer);flushResolver=resolve;flushRejecter=reject;flushTimer=setTimeout(()=>{flushResolver=null;flushRejecter=null;flushTimer=null;reject(new Error('Timed out waiting for the final note flush.'))},timeout)})}
function releaseAudio(){if(node){try{node.disconnect()}catch(error){}if(node.port)node.port.onmessage=null;node.onaudioprocess=null;node=null}if(stream){stream.getTracks().forEach(track=>track.stop());stream=null}if(ctx){const old=ctx;ctx=null;old.close().catch(()=>{})}}
function microphoneError(error){const name=error&&error.name;if(name==='NotAllowedError'||name==='PermissionDeniedError')return new Error('Microphone permission was denied. Allow microphone access for this page, then try again.');if(name==='NotFoundError')return new Error('No microphone was found. Connect an input device and try again.');if(name==='NotReadableError'||name==='TrackStartError')return new Error('The microphone is busy or unavailable to the browser. Close other recording apps and try again.');if(name==='SecurityError')return new Error('The browser blocked microphone access. Open NoteTaker on localhost or HTTPS.');return new Error('Could not access the microphone'+(error&&error.message?': '+error.message:''))}
function sendSamples(samples){if(!running||!ws||ws.readyState!==WebSocket.OPEN)return;const values=samples instanceof Float32Array?samples:new Float32Array(samples);const pcm=new Int16Array(values.length);for(let i=0;i<values.length;i++){const value=Math.max(-1,Math.min(1,values[i]));pcm[i]=value<0?value*32768:value*32767}ws.send(pcm.buffer)}
function selectedModelOption(){return modelOptions.find(option=>option.id===(($('#model-select')&&$('#model-select').value)||selectedModel))||fallbackModelOptions[0]}
function updateModelHelp(){const option=selectedModelOption();if(option)$('#model-help').textContent=`${option.description} CPU only · ${option.speed} · ${option.quality} quality${option.parameters?' · '+option.parameters:''}.`}
function renderModelOptions(options){const available=Array.isArray(options)&&options.length>=5?options:fallbackModelOptions;modelOptions=available;const select=$('#model-select');if(!select)return;select.innerHTML=modelOptions.map(option=>`<option value="${escapeHtml(option.id)}">${escapeHtml(option.label)}</option>`).join('');if(!modelOptions.some(option=>option.id===selectedModel))selectedModel='large-v3-turbo';select.value=selectedModel;updateModelHelp()}
async function loadModelOptions(){try{const response=await fetch('/api/models');if(!response.ok)throw new Error('model list request failed');const data=await response.json();renderModelOptions(data.models)}catch(error){renderModelOptions(fallbackModelOptions);$('#model-help').textContent='Using the built-in model list. All choices stay on CPU.'}}
function setModelPickerLocked(locked){const select=$('#model-select');if(select)select.disabled=locked}
function rememberModel(){try{localStorage.setItem('notetaker-model',selectedModel)}catch(error){}}
function handleSocketMessage(event){let message;try{message=JSON.parse(event.data)}catch(error){showError(new Error('Received an invalid message from NoteTaker'));return}if(message.t==='ready'){if(message.model_options)renderModelOptions(message.model_options);setModelState(message.model_status);setStatus('connected','Microphone is ready. Speak when you see the level meter move.')}else if(message.t==='vad'){if(message.fallback){setStatus('listening','Audio pipeline ready with energy fallback.');$('#message').textContent='Silero VAD is unavailable; install onnxruntime for the strongest boundary detection.'}else if(message.state==='updated')$('#message').textContent='VAD backend confirmed: '+message.backend+'.';else setStatus('listening','Audio pipeline ready at '+message.sample_rate+' Hz.')}else if(message.t==='model'){setModelState(message);if(message.state==='loading')setStatus('loading model','The first capture downloads/loads the configured Whisper models.');else if(message.state==='ready'&&!flushPending)setStatus('listening','Models ready; speak normally.')}else if(message.t==='benchmark')showBenchmark(message);else if(message.t==='level'){$('#meter').style.width=Math.round(message.v*100)+'%';updateQueue(message.lag);if(message.on&&!speechDetectedAt)speechDetectedAt=Date.now();if(running&&$('#status').textContent!=='error'&&$('#status').textContent!=='loading model'&&$('#status').textContent!=='finishing')$('#status').textContent=message.on?'speech':'listening'}else if(message.t==='partial'){setStatus('drafting','Draft transcription is updating…');showPartial({...message,start:message.start||0,end:message.end||0})}else if(message.t==='segment')addSegment(message);else if(message.t==='empty'){const live=$('#live');if(live.querySelector('.empty'))live.innerHTML='';live.append(renderEmpty('No speech recognised in this segment',message.reason||'The decoder returned no segments.'));live.scrollTop=live.scrollHeight;setStatus('no speech','The audio segment contained no recognised speech.')}else if(message.t==='audio-config')$('#message').textContent='Audio rate '+Math.round(message.source_rate)+' Hz → '+message.target_rate+' Hz.';else if(message.t==='note')setStatus('saved · '+message.title,'Capture saved to the local knowledge base.');else if(message.t==='flushed'){setModelPickerLocked(false);$('#record').textContent='Start capture';$('#record').classList.remove('live');resolveFlush(message);setStatus(message.saved?'saved':'no speech detected',message.saved?'Final transcript saved to the local knowledge base.':'No speech segment was detected; keep the microphone level meter visible and try again.')}else if(message.t==='error'){setModelState(message.models);showError(new Error(message.message||'Capture failed.'))}}
async function capture(){if(running)return;const localHost=['localhost','127.0.0.1','::1'].includes(location.hostname);if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia)throw new Error('This browser does not expose microphone capture. Use a current browser on localhost or HTTPS.');if(!window.isSecureContext&&!localHost)throw new Error('Microphone access requires HTTPS or localhost.');setStatus('requesting microphone','The browser should ask for microphone permission now.');try{try{stream=await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:true,noiseSuppression:true,autoGainControl:true}})}catch(error){throw microphoneError(error)}setStatus('connecting','Microphone permission granted; connecting to the transcription service…');ws=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/ws?model='+encodeURIComponent(selectedModel));ws.binaryType='arraybuffer';ws.onmessage=handleSocketMessage;ws.onclose=()=>{setModelPickerLocked(false);if(!running){$('#record').textContent='Start capture';$('#record').classList.remove('live')}if(flushPending){if(flushRejecter)flushRejecter(new Error('The capture connection closed before the note was flushed.'));flushPending=false}else if(running)showError(new Error('The capture connection closed. Check the server terminal for details.'))};await waitForSocket(ws);const AudioContextClass=window.AudioContext||window.webkitAudioContext;if(!AudioContextClass)throw new Error('This browser does not support the Web Audio API.');ctx=new AudioContextClass({sampleRate:16000});if(ctx.state==='suspended')await ctx.resume();if(ctx.state==='suspended')throw new Error('The browser suspended audio capture. Press Start capture again to allow audio.');sourceRate=ctx.sampleRate||16000;ws.send(JSON.stringify({t:'config',sample_rate:sourceRate,model:selectedModel}));const source=ctx.createMediaStreamSource(stream);if(ctx.audioWorklet&&typeof AudioWorkletNode!=='undefined'){const worklet=`class C extends AudioWorkletProcessor{constructor(){super();this.b=new Float32Array(1024);this.i=0}process(x){const c=x[0]&&x[0][0];if(!c)return true;for(const v of c){this.b[this.i++]=v;if(this.i===1024){this.port.postMessage(this.b.slice());this.i=0}}return true}}registerProcessor('capture',C)`;const moduleUrl=URL.createObjectURL(new Blob([worklet],{type:'application/javascript'}));await ctx.audioWorklet.addModule(moduleUrl);URL.revokeObjectURL(moduleUrl);node=new AudioWorkletNode(ctx,'capture');node.port.onmessage=event=>sendSamples(event.data)}else if(ctx.createScriptProcessor){node=ctx.createScriptProcessor(4096,1,1);node.onaudioprocess=event=>sendSamples(event.inputBuffer.getChannelData(0))}else throw new Error('This browser cannot create an audio capture processor.');const gain=ctx.createGain();gain.gain.value=0;source.connect(node);node.connect(gain).connect(ctx.destination);running=true;flushPending=false;setModelPickerLocked(true);$('#record').textContent='Stop capture';$('#record').classList.add('live');setStatus('listening','Audio capture is active.')}catch(error){setModelPickerLocked(false);releaseAudio();if(ws&&ws.readyState<2)ws.close();ws=null;throw error}}
async function stop(){if(!running&&!stream&&!flushPending)return;running=false;if(ws&&ws.readyState===WebSocket.OPEN){flushPending=true;setModelPickerLocked(true);setStatus('finishing','Finishing the current speech segment and saving the note…');const waiter=waitForFlush();ws.send(JSON.stringify({t:'flush'}));releaseAudio();try{const message=await waiter;flushPending=false;setModelPickerLocked(false);if(ws&&ws.readyState===WebSocket.OPEN)ws.close();return message}catch(error){flushPending=false;setModelPickerLocked(false);showError(error);if(ws&&ws.readyState<2)ws.close()}}else{releaseAudio();setModelPickerLocked(false);setStatus('stopped','Capture stopped.')}}
$('#model-select').onchange=()=>{if(running||flushPending){showError(new Error('Wait for capture to finish before changing the model.'));$('#model-select').value=selectedModel;return}selectedModel=$('#model-select').value;rememberModel();const option=selectedModelOption();$('#model').textContent=option.label;updateModelHelp();setStatus('model selected',`${option.label} will load on the next capture. It stays on CPU.`)};
$('#record').onclick=()=>running?stop().catch(showError):capture().catch(showError);$('#clear').onclick=()=>{$('#live').innerHTML='<div class="empty">Live view cleared. Saved notes remain searchable.</div>';segments=[];lines=[];draftNode=null;$('#words').textContent='0 words';showBanner('watchdog-banner','')};
window.addEventListener('beforeunload',event=>{if(flushPending){event.preventDefault();event.returnValue='A final NoteTaker flush is still pending.';return event.returnValue}});
setInterval(()=>{if(!running||!speechDetectedAt)return;if(Date.now()-speechDetectedAt<45000||lastOutputAt>=speechDetectedAt)return;const queue=$('#queue').textContent,rtf=measuredRtf===null?'unknown':measuredRtf.toFixed(2)+'×';showBanner('watchdog-banner',`Speech is detected but no transcript has arrived for 45s. ${queue}; measured RTF ${rtf}. Switch to a faster model or wait for the queue to drain.`,true)},1000);
async function search(){try{const q=encodeURIComponent($('#query').value);const response=await fetch('/api/notes?query='+q);const data=await response.json();$('#results').innerHTML=data.length?data.map(n=>`<div class="result"><a onclick="openNote('${escapeHtml(n.id)}')">${escapeHtml(n.title)}</a><div class="hint">${escapeHtml(n.source_type)} · ${stamp(n.duration)} · ${escapeHtml(n.created_at)}</div></div>`).join(''):'<div class="empty">No matching evidence yet.</div>'}catch(error){$('#results').innerHTML='<div class="empty">Search is temporarily unavailable.</div>'}}
async function openNote(id){const n=await fetch('/api/notes/'+encodeURIComponent(id)).then(response=>response.json());$('#selected').innerHTML=`<div class="note-card"><strong>${escapeHtml(n.title)}</strong><ul>${(n.executive_summary||[]).map(item=>'<li>'+escapeHtml(item)+'</li>').join('')}</ul><div class="exports">${['md','pdf','docx','json','html','anki'].map(format=>`<a href="/api/notes/${encodeURIComponent(n.id)}/export/${format}" target="_blank">export ${format}</a>`).join(' · ')}</div></div>`}
async function checkHealth(){try{const response=await fetch('/api/health');if(!response.ok)throw new Error('health check failed');const data=await response.json();setModelState(data.models)}catch(error){$('#message').textContent='Could not read model status; the server may still be starting.'}}
$('#search').onclick=search;$('#query').onkeydown=event=>{if(event.key==='Enter')search()};renderModelOptions(fallbackModelOptions);loadModelOptions();checkHealth();search();
</script></body></html>'''
